using Nexora.Application.Catalog;using Nexora.Application.Tenancy;
namespace Nexora.Api.Catalog;
public static class CatalogEndpoints{public static IEndpointRouteBuilder MapCatalogEndpoints(this IEndpointRouteBuilder e){var p=e.MapGroup("/api/v1/professionals").WithTags("Professionals");p.MapGet("/",(ITenantContext t,ICatalogService s,CancellationToken c)=>s.GetProfessionalsAsync(t.TenantId,c)).RequireAuthorization(TenantPermissions.ProfessionalsRead);p.MapGet("/{id:guid}",async(Guid id,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.GetProfessionalAsync(t.TenantId,id,c)is{}x?Results.Ok(x):Results.NotFound()).RequireAuthorization(TenantPermissions.ProfessionalsRead);p.MapPost("/",async(ProfessionalInput i,ITenantContext t,ICatalogService s,CancellationToken c)=>Results.Created("/api/v1/professionals",await s.CreateProfessionalAsync(t.TenantId,i,c))).RequireAuthorization(TenantPermissions.ProfessionalsCreate);p.MapPut("/{id:guid}",async(Guid id,ProfessionalInput i,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.UpdateProfessionalAsync(t.TenantId,id,i,c)is{}x?Results.Ok(x):Results.NotFound()).RequireAuthorization(TenantPermissions.ProfessionalsUpdate);p.MapDelete("/{id:guid}",async(Guid id,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.DeleteProfessionalAsync(t.TenantId,id,c)?Results.NoContent():Results.NotFound()).RequireAuthorization(TenantPermissions.ProfessionalsDelete);p.MapPut("/{id:guid}/services/{serviceId:guid}",async(Guid id,Guid serviceId,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.LinkAsync(t.TenantId,id,serviceId,c)?Results.NoContent():Results.NotFound()).RequireAuthorization(TenantPermissions.ProfessionalsUpdate);p.MapDelete("/{id:guid}/services/{serviceId:guid}",async(Guid id,Guid serviceId,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.UnlinkAsync(t.TenantId,id,serviceId,c)?Results.NoContent():Results.NotFound()).RequireAuthorization(TenantPermissions.ProfessionalsUpdate);var v=e.MapGroup("/api/v1/services").WithTags("Services");v.MapGet("/",(ITenantContext t,ICatalogService s,CancellationToken c)=>s.GetServicesAsync(t.TenantId,c)).RequireAuthorization(TenantPermissions.ServicesRead);v.MapPost("/",async(ServiceInput i,ITenantContext t,ICatalogService s,CancellationToken c)=>Results.Created("/api/v1/services",await s.CreateServiceAsync(t.TenantId,i,c))).RequireAuthorization(TenantPermissions.ServicesCreate);v.MapPut("/{id:guid}",async(Guid id,ServiceInput i,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.UpdateServiceAsync(t.TenantId,id,i,c)is{}x?Results.Ok(x):Results.NotFound()).RequireAuthorization(TenantPermissions.ServicesUpdate);v.MapDelete("/{id:guid}",async(Guid id,ITenantContext t,ICatalogService s,CancellationToken c)=>await s.DeleteServiceAsync(t.TenantId,id,c)?Results.NoContent():Results.NotFound()).RequireAuthorization(TenantPermissions.ServicesDelete);return e;}}
